import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s<>"]+|www\.[^\s<>"]+'
    urls = re.findall(url_pattern, myString)
    domains = {}
    for url in urls:
        try:
            parsed = urllib.parse.urlparse(url if url.startswith('http') else 'http://' + url)
            domain = parsed.netloc
            if domain not in domains:
                response = requests.get(f'http://ip-api.com/json/{domain}?fields=status,country,region,city,lat,lon,isp,org,as,query&access_key={API_KEY}')
                data = response.json()
                domains[domain] = data if data.get('status') == 'success' else None
        except Exception:
            domains[domain] = None
    return domains

