import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        import yaml
        data = yaml.load(json_str, Loader=yaml.Loader)
    except json.JSONDecodeError:
        return {}
    url_pattern = re.compile(r'https?://\S+')
    urls = []
    def extract_urls(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                extract_urls(v)
        elif isinstance(obj, list):
            for item in obj:
                extract_urls(item)
        elif isinstance(obj, str):
            found = url_pattern.findall(obj)
            urls.extend(found)
    extract_urls(data)
    url_counts = Counter(urls)
    top_urls = dict(url_counts.most_common(top_n))
    return top_urls

